import{d as m,C as t,o as c,c as u,j as a,a as i,E as n,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第二十章","description":"从唯阿美恶的追问、众人与我独的对照，读到贵食母的根本取向。","frontmatter":{"title":"道德经第二十章","description":"从唯阿美恶的追问、众人与我独的对照，读到贵食母的根本取向。","category":"guide","aliases":["道德经第二十章","老子第二十章","dao de jing chapter 20"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-20.md","filePath":"daoism/dao-de-jing/chapter-20.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-20.md"},w=m({...p,setup(g){const r=[{id:"responses-judgements-and-fear",label:"唯之与阿，相去几何",showLabel:!0,sentences:[[{text:"唯",glossary:"wei"},"之与",{text:"阿",glossary:"e"},"，相去",{text:"几何",glossary:"jihe"},"？"],["美之与",{text:"恶",glossary:"e-ugly"},"，相去若何？人之所畏，不可不畏。"]],note:["【白话】恭敬应诺的唯与较随便应答的阿，相差有多少？美与不美，相差又有多少？人们所畏惧的，我也不能全不畏惧。","【王弼注择要】「故人之所畏，吾亦畏焉。」注没有把对唯阿、美恶差别的追问推成全然不顾共同处境。本页接上章绝学无忧，先看对评价与进取的反省。","【读法】唯、阿在此均为应答声，二者礼貌与语气的差别是一种解释；唯本页读 wéi，亦有 wěi 的标音。恶取不美义，读 è，不读厌恶的 wù。"]},{id:"the-crowd-in-festivity",label:"众人熙熙，如享太牢",showLabel:!0,sentences:[["荒兮其",{text:"未央",glossary:"weiyang"},"哉！众人熙熙，如享",{text:"太牢",glossary:"tailao"},"，如春登台。"]],note:["【白话】辽远啊，仿佛没有尽头！众人兴高采烈，像赴丰盛的宴享，又像春天登台游赏。","【王弼注择要】荒兮一语，注说「叹与俗相返之远也」。又以「迷于美进，惑于荣利」解释众人的热切，已为下文我独的反差设下背景。","【读法】太牢原是牛羊豕俱备的祭牲之称，这里用来写盛大宴享。诗性的众人形象不宜当成对现实中每一个人的事实判断。"]},{id:"quiet-and-seemingly-without-a-home",label:"我独泊兮其未兆",showLabel:!0,sentences:[["我独",{text:"泊",glossary:"bo"},"兮其未兆，如婴儿之",{text:"未孩",glossary:"weihai"},"；"],[{text:"儽儽",glossary:"leilei"},"兮若无所归。众人皆有余，而我独若",{text:"遗",glossary:"yi"},"。"]],note:["【白话】唯独我恬静，尚未显出意向，像还没有发笑的婴儿；疲困而无所依归的样子啊。众人都像有所充盈，唯独我仿佛有所遗失。","【王弼注择要】「无形之可名，无兆之可举。」解释若无所归，注说「若无所宅」；解释若遗，注说「若遗失之也」。注反复指向不显定向、不据定处的样态。","【读法】孩在这里取婴儿发笑义，不是成年以前的年龄分类。儽儽本页依辞书读 lěi lěi；遗取仿佛失落、遗失义，与第九章留下、招致咎患义分开。"]},{id:"not-displaying-clever-discernment",label:"俗人昭昭，我独昏昏",showLabel:!0,sentences:[["我愚人之心也哉，",{text:"沌沌",glossary:"dundun"},"兮！"],["俗人",{text:"昭昭",glossary:"zhaozhao"},"，我独昏昏；"],["俗人",{text:"察察",glossary:"chacha"},"，我独",{text:"闷闷",glossary:"menmen"},"。"]],note:["【白话】我的心真像愚人啊，浑沌未分！世俗之人显得明白昭著，我独像昏暗不明；世俗之人显得精细明察，我独像浑厚而不辨析。","【王弼注择要】「心无所别析，意无所好欲。」昭昭，注释「耀其光也」；察察，注释「分别别析也」。对照落在是否将分辨、欲向与光彩不断显露出来。","【读法】原文保留愚、昏、闷的自述，不能全换成聪明的赞辞；依注又可看出它反省的是机巧分别与显耀，并非要求遇到具体问题时拒绝辨认事实。"]},{id:"wide-open-and-without-fixed-use",label:"澹兮其若海，飂兮若无止",showLabel:!0,sentences:[[{text:"澹",glossary:"dan"},"兮其若海，",{text:"飂",glossary:"liu"},"兮若无止。"],["众人皆",{text:"有以",glossary:"youyi"},"，而我独",{text:"顽且鄙",glossary:"wanqiebi"},"。"]],note:["【白话】浩渺啊，像大海；飘荡啊，像没有固定停处。众人都各有施用的目的，我却独显得愚钝而朴陋。","【王弼注择要】若海，注说「情不可睹」；若无止，注说「无所系絷」。有以，注释「以，用也」，又说「皆欲有所施用也」。相对而言，我独不急于把自身安置为某种既定功用。","【读法】飂本页读 liù，取飘动之貌。顽鄙是与世俗所重相对的自述，不能据此把缺少基本能力、拒绝承担责任直接认作有道。"]},{id:"nourished-by-the-root",label:"我独异于人，而贵食母",showLabel:!0,sentences:[["我独异于人，而贵",{text:"食母",glossary:"shimu"},"。"]],note:["【白话】我独与人不同，在于珍重从生养的根本取得滋养。这一句为前面看似失落、愚钝的样态指出所依归的方向。","【王弼注择要】「食母，生之本也。」注又说「贵末饰之华」，以此对照离本逐末的取向。母在这里联系生养所由的根本。","【读法】全章不以异于人为最终目的，而是以贵食母说明不同的所贵。现代读者可由此追问何者真正养我，不必以故意与众不同证明自己更高。"]}],s=[{id:"wei",term:"唯",sense:1,pinyin:"wéi"},{id:"e",term:"阿",sense:1,pinyin:"ē"},{id:"jihe",term:"几何",sense:1,pinyin:"jǐ hé"},{id:"e-ugly",term:"恶",sense:2,pinyin:"è"},{id:"weiyang",term:"未央",sense:1},{id:"tailao",term:"太牢",sense:1},{id:"bo",term:"泊",sense:1,pinyin:"bó"},{id:"weihai",term:"未孩",sense:1},{id:"leilei",term:"儽儽",sense:1,pinyin:"lěi lěi"},{id:"yi",term:"遗",sense:2},{id:"dundun",term:"沌沌",sense:1},{id:"zhaozhao",term:"昭昭",sense:1},{id:"chacha",term:"察察",sense:1},{id:"menmen",term:"闷闷",sense:1,pinyin:"mèn mèn"},{id:"dan",term:"澹",sense:1,pinyin:"dàn"},{id:"liu",term:"飂",sense:1,pinyin:"liù"},{id:"youyi",term:"有以",sense:1},{id:"wanqiebi",term:"顽且鄙",sense:1},{id:"shimu",term:"食母",sense:1,pinyin:"shí mǔ"}];return(y,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十章",tabindex:"-1"},[i("道德经第二十章 "),a("a",{class:"header-anchor",href:"#道德经第二十章","aria-label":'Permalink to "道德经第二十章"'},"​")],-1)),n(o,{title:"我独的不同，最终贵在什么？",summary:"本章先追问应答与美恶的差别，再用众人的热切、明察、有所施用，与我独的恬静、失落、愚钝相照。最后贵食母点出根本取向，使不同不只停在孤独或反常的姿态。",points:[{label:"先读",text:"众人、俗人与我独，各有哪些相对的样态？"},{label:"再辨",text:"不逐世俗所贵，为什么仍有不可不畏？"},{label:"后想",text:"食母如何说明我独的所依，而非只强调差异？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[i("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:r,glossary:s,tone:"ink",density:"comfortable","aria-label":"《道德经》第二十章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[i("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"人之所畏，不可不畏。",tone:"差别之外仍须顾及",guide:"前两问使既有评价受到追问，这一句却没有允许人从共同处境中彻底抽身。依王弼，人之所畏，吾亦畏焉。"},{text:"众人皆有余，而我独若遗。",tone:"保留失落的笔触",guide:"这里不只是宣告我比众人高。若遗让不随众的处境带有失落与无所依归的样貌，读时不必急着消掉这份张力。"},{text:"众人皆有以，而我独顽且鄙。",tone:"辨所用与所贵",guide:"有以循王弼作各有施用来读。原文不急于展示一种可以立刻换取评价的用处，下一句才说真正看重的根本。"},{text:"我独异于人，而贵食母。",tone:"收回根本",guide:"异于人的理由落在食母，而非为了显得独特。以生养之本校准所贵，是本章结尾给出的方向。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[i("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-众人与我独的反差怎样推进" tabindex="-1">象：众人与我独的反差怎样推进？ <a class="header-anchor" href="#象-众人与我独的反差怎样推进" aria-label="Permalink to &quot;象：众人与我独的反差怎样推进？&quot;">​</a></h3><p>先是热闹与恬静、有余与若遗，再是昭察与昏闷、有所施用与顽鄙。描述不断加深，直到食母才说明不同的根由。若只摘取我独一句，容易将章旨缩成孤独的姿态，遗漏所依归的生养之本。</p><h3 id="理-愚、昏、闷是在赞美无知吗" tabindex="-1">理：愚、昏、闷是在赞美无知吗？ <a class="header-anchor" href="#理-愚、昏、闷是在赞美无知吗" aria-label="Permalink to &quot;理：愚、昏、闷是在赞美无知吗？&quot;">​</a></h3><p>原文确实采用这些负面的自述，不能将其锋芒全部改写掉。王弼则用不显意向、不好欲、不分别炫明来解释。循此可读出对机巧与逐名的反省，但仍须与事实判断、实际能力区分，不因自称愚昏便免于说明与检验。</p><h3 id="用-不随众-如何仍与他人共同生活" tabindex="-1">用：不随众，如何仍与他人共同生活？ <a class="header-anchor" href="#用-不随众-如何仍与他人共同生活" aria-label="Permalink to &quot;用：不随众，如何仍与他人共同生活？&quot;">​</a></h3><p>可以不以热闹、显耀和即时功用决定全部选择，同时顾及共同风险、履行约定、理解他人的需要。人之所畏不可不畏提醒这种联系仍在；独立取舍并不需要将所有人都写成迷失者。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>区分养分与证明。</strong> 选择学习、工作或表达方向时，可以问它是在滋养长期能力与生活，还是只为显得比别人更忙、更清醒、更特别。食母提供的是追问根本的譬喻，不替代具体取舍。</p><p><strong>允许不同，也检查后果。</strong> 一项选择暂时不受欢迎，并不自动证明它错；同样，不受欢迎也不能证明它更接近道。仍需看真实需要、可承担的代价与对他人的影响。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我想坚持的不同，究竟依归何处？如果没有旁人的赞许或反对，它是否仍能真实地滋养我的生活与行动？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站把「绝学无忧」保留在第十九章末，本页从「唯之与阿」接读；所据录文在此段开头连写「绝学无忧」。两页合看不漏句，也不重复原文。</li><li>正文保留本站「美之与恶」「我独泊兮」「我独昏昏」「顽且鄙」；HFL 录文分别见「善之与恶」「我独怕兮」「我独若昏」「顽似鄙」，差异在此明记，不混入正文。</li><li>儽儽本页依辞书读 lěi lěi，未孩循王弼作尚未发笑解；飂读 liù、取飘动义。唯、阿的语气区分与唯的标音有不同取法，本页明确采用应答声的解释。</li><li>遗在若遗中另立遗失义，食母循王弼「生之本」理解；不沿用其他章节的字义来硬套本章。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，012b–013b</a>；字音参看<a href="https://www.zdic.net/hans/%E5%94%AF%E9%98%BF" target="_blank" rel="noreferrer">汉典「唯阿」</a>、<a href="https://www.zdic.net/hans/%E5%84%BD%E5%84%BD" target="_blank" rel="noreferrer">「儽儽」</a>、<a href="https://www.zdic.net/hans/%E9%A3%82" target="_blank" rel="noreferrer">「飂」</a>。</p>',15))])}}});export{f as __pageData,w as default};
